components.analogy:
JavaScript 面试中最令候选人头疼的经典陷阱之一：
for (var i = 0; i < 3; i++) {
  setTimeout(function() {
    console.log(i);  // 你期待 0, 1, 2 吗？
  }, 1000);
}
实际输出：<code>3, 3, 3</code>！<br><br>为什么三个不同时刻注册的回调函数，最终都打印了同一个值？这是一个关于 <b>变量作用域</b> 与 <b>闭包（Closure）</b> 的核心问题——函数在「定义时」捕获的是变量的引用，而不是值的副本。理解这一机制，是真正掌握 JavaScript 的关键。

components.example:
// 闭包经典用法：用工厂函数创建一个带有私有状态的计数器；外部只能通过返回的方法间接操作 count，而不能直接改写它。
function makeCounter() {
  let count = 0;  // count 被封存在闭包中；即使 makeCounter 已经执行完，这个变量仍会被返回的方法保留。
  return {
    increment() { count++; }, // 每次调用只增加内部状态，不把变量本身暴露给外部。
    decrement() { count--; }, // 通过受控的方法减少状态，调用者不需要知道 count 存在哪里。
    value()     { return count; } // 读取当前值，形成一个清晰的“读接口”。
  };
}
const counter = makeCounter();
counter.increment();
counter.increment();
console.log(counter.value()); // 2；这里可以读取结果，但无法直接访问 counter.count。
// count 变量从外部无法直接访问，这就是闭包实现“私有变量”的基本方式。

components.content:
在 JavaScript 原生引入 `#private` 私有字段之前，社区长期使用闭包来实现封装与私有状态保护（如 Redux store、防抖函数 `debounce` 等）：

```javascript
// 手写闭包模块模式 (Module Pattern)
const UserStore = (function() {
  // 私有变量，保存在闭包词法环境中，外部无法直接访问
  let _token = "secret_bearer_token_999";
  let _user = { name: "Alice", role: "admin" };

  return {
    // 仅暴露安全的 Getter 和 Setter 接口
    getUser() {
      return { ..._user }; // 返回浅拷贝防止引用污染
    },
    setToken(newToken) {
      if (typeof newToken === "string") _token = newToken;
    }
  };
})();

console.log(UserStore.getUser()); // { name: "Alice", role: "admin" }
console.log(UserStore._token);     // undefined (私有变量安全保护)
```

> 💡 **架构意义**：防抖 (Debounce)、节流 (Throttle) 以及现代框架 Hooks (如 React `useState`) 的底层原理完全建立在这一闭包模式之上！

questions.question:
下面代码的输出是什么？

```javascript
function outer() {
  let x = 10;
  function inner() {
    x += 5;
    return x;
  }
  return inner;
}
const fn = outer();
console.log(fn()); // 第一次调用
console.log(fn()); // 第二次调用
```
